package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTlDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("Nakikita ang Unang Bunga", "O Allah, pagpalain Mo kami sa aming bunga, pagpalain kami sa aming lungsod, at pagpalain kami sa aming sa' at aming mudd (mga sukat).", "Nang makita ang unang bunga ng panahon.", "Isang panalangin para sa pagpapala sa probisyon at sa sariling lungsod."),
        "dua_good_news" to DuaText("Sa Nakalulugod na Balita", "Ang lahat ng papuri ay para sa Allah, na sa pamamagitan ng Kanyang paglingap ay natatapos ang mabubuting bagay.", "Sa pagtanggap ng mabuting balita (at isagawa ang pagpapatirapa ng pasasalamat).", "Ang Propeta ﷺ ay nagsabi nito sa pagkakita ng isang bagay na kanyang nagustuhan."),
        "dua_looking_mirror" to DuaText("Nakatingin sa Salamin", "O Allah, kung paanong pinaganda Mo ang aking anyo, gawin mo rin ang aking pagkatao.", "Kapag tumitingin sa salamin.", "Ginawa ng Propeta ﷺ ang dua na ito (ito ay itinatag kahit na walang pagbanggit ng salamin)."),
        "dua_rabbana_taqabbal" to DuaText("Pagtanggap sa mga Gawa", "Panginoon namin, tanggapin mo ito mula sa amin; tunay na Ikaw ang Ganap na Nakaririnig, ang Nakaaalam ng Lahat. At tanggapin ang aming pagsisisi; tunay na Ikaw ang Tagatanggap ng pagsisisi, ang Maawain.", "Tinanong nina Ibrahim at Isma'il (AS) habang itinatayo ang Ka'bah.", "Isang panalangin para sa pagtanggap pagkatapos ng bawat mabuting gawa."),
        "dua_muawwidhat" to DuaText("Ang Tatlong Quls (Mu'awwidhat)", "(Surah al-Ikhlas) Sabihin: Siya ang Allah, ang Nag-iisa. Si Allah, ang Sapat sa Sarili. Hindi siya nanganak o ipinanganak. At walang maihahambing sa Kanya.\n\n(Surah al-Falaq) Sabihin: Ako ay nagpapakupkop sa Panginoon ng bukang-liwayway, mula sa kasamaan ng Kanyang nilikha, mula sa kasamaan ng kadiliman kapag ito ay naninirahan, mula sa kasamaan ng mga humihihip sa mga buhol, at mula sa kasamaan ng naiinggit kapag siya ay naiinggit.\n\n(Surah an-Nas) Sabihin: Ako ay nagpapakupkop sa Panginoon ng sangkatauhan, ang Hari ng sangkatauhan, ang Diyos ng sangkatauhan, mula sa kasamaan ng umaatras na bulong, na bumubulong sa puso ng sangkatauhan, mula sa mga jinn at sangkatauhan.", "Ang tatlong surah ng tatlong beses tuwing umaga at gabi, at bago matulog, hipan sa mga kamay at punasan ang mga ito sa katawan.", "Ang pagbigkas ng mga ito ng tatlong beses sa umaga at gabi ay sapat na laban sa lahat."),
        "dua_sabr" to DuaText("Para sa Pasensya at Katatagan", "Panginoon, ibuhos mo sa amin ang pasensya, patatagin mo ang aming mga paa at tulungan mo kami laban sa mga taong hindi naniniwala.", "Sa panahon ng kahirapan at paghaharap.", "Ang dua ng hukbo ni Talut."),
        "dua_rabbana_innana_amanna" to DuaText("Pagpapatawad at Proteksyon mula sa Apoy", "Panginoon namin, kami ay nanampalataya, kaya patawarin mo kami sa aming mga kasalanan at ingatan mo kami mula sa kaparusahan ng Apoy.", "Isang Quranic na dua.", "Isang dua na binanggit sa mga katangian ng may takot sa Diyos."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Patnubay sa Ating Pakikipag-ugnayan (Ashab al-Kahf)", "Panginoon namin, bigyan mo kami ng awa mula sa Iyong sarili at ihanda mo kami sa tamang patnubay sa aming gawain.", "Ang dua ng mga Tao ng Cave.", "Patnubay sa mga desisyon at mahihirap na sitwasyon."),
        "dua_musa_faqir" to DuaText("Dua ng Musa (AS) para sa Probisyon", "Panginoon ko, ako ay tunay na nangangailangan ng anumang kabutihang ipinadala Mo sa akin.", "Naghahanap ng panustos at kabutihan — ang dua ni Musa (AS) sa Madyan.", "Pagkatapos ng dalawang ito, pinagkalooban ng Allah si Musa (AS) ng tahanan, trabaho at asawa."),
        "dua_ayyub" to DuaText("Dua ng Ayyub (AS) sa Sakit", "(Aking Panginoon,) sinaktan ako ng pinsala, at Ikaw ang Pinakamaawain sa mga mahabagin.", "Sa sakit at pagdurusa.", "Inalis ng Allah ang pagdurusa ni Ayyub (AS)."),
        "dua_husn_khatimah" to DuaText("Mamatay bilang isang Muslim (Yusuf AS)", "Lumikha ng langit at lupa, Ikaw ang aking Tagapagtanggol sa mundong ito at sa Kabilang Buhay. Nawa'y mamatay ako bilang isang Muslim at isama ako sa mga matuwid.", "Isang dalawang para sa isang magandang pagtatapos.", "Ang dua ni Propeta Yusuf (AS)."),
        "dua_shaitan_hamazat" to DuaText("Kanlungan mula sa mga Bulong ng Diyablo", "Aking Panginoon, ako ay nagpapakupkop sa Iyo mula sa mga bulong ng mga demonyo, at ako ay nagpapakupkop sa Iyo, aking Panginoon, baka sila ay lumapit sa akin.", "Kanlungan mula sa mga bulong ni satanas.", "Isang Quranic na dua ng paghahanap ng kanlungan."),
        "dua_bad_character" to DuaText("Kanlungan mula sa Masamang Ugali", "O Allah, ako ay nagpapakupkop sa Iyo mula sa masamang ugali, masamang gawain at masasamang pagnanasa.", "Kanlungan mula sa masamang ugali, gawa at pagnanasa.", "Isang dua ng kanlungan mula sa Propeta ﷺ."),
        "dua_zawal_nimah" to DuaText("Kanlungan mula sa Pagkawala ng mga Pagpapala", "O Allah, ako ay nagpapakupkop sa Iyo mula sa pagkawala ng Iyong mga pagpapala, mula sa pagbabago ng kagalingang Iyong ibinigay, mula sa Iyong biglaang pagpaparusa at mula sa lahat ng Iyong sama ng loob.", "Kanlungan mula sa pagkawala ng mga pagpapala at mula sa biglaang kapahamakan.", "Isang panalangin ng Propeta ﷺ."),
        "dua_useless_knowledge" to DuaText("Kanlungan mula sa Hindi Kapaki-pakinabang na Kaalaman", "O Allah, ako ay nagpapakupkop sa Iyo mula sa kaalaman na hindi nakikinabang, mula sa isang pusong hindi natatakot, mula sa isang kaluluwang hindi nasisiyahan, at mula sa isang dua na hindi sinasagot.", "Kanlungan mula sa walang kwentang kaalaman at isang pusong walang takot kay Allah.", "Isang dua ng kanlungan mula sa Propeta ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Kapaki-pakinabang na Kaalaman at Halal Rizq", "O Allah, humihingi ako sa Iyo ng kapaki-pakinabang na kaalaman, dalisay na panustos at tinatanggap na mga gawa.", "Pagkatapos ng pagdarasal ng Fajr.", "Ang Propeta ﷺ ay nagsabi nito pagkatapos ng salam ng Fajr."),
        "dua_leprosy_diseases" to DuaText("Kanlungan mula sa Malubhang Sakit", "O Allah, ako ay nagpapakupkop sa Iyo mula sa vitiligo, kabaliwan, ketong at lahat ng masasamang sakit.", "Proteksyon mula sa malubhang sakit.", "Isang Sunnah dua para sa pagpapanatili ng kalusugan."),
        "dua_fear_people" to DuaText("Takot sa mga Kaaway o Maniniil", "O Allah, inilalagay ka namin sa harap nila at nagpapakupkop kami sa Iyo mula sa kanilang kasamaan.", "Kapag natatakot sa pinsala ng isang tao o isang tao.", "Ang Propeta ﷺ ay nagsabi nito nang siya ay natakot sa isang tao."),
        "dua_shirk_protection" to DuaText("Proteksyon mula sa Nakatagong Shirk", "O Allah, ako ay nagpapakupkop sa Iyo mula sa sadyang pagtatambal ng anuman sa Iyo, at ako ay humihingi ng Iyong kapatawaran sa kung ano ang hindi ko nalalaman.", "Para manatiling ligtas sa pagpapakitang gilas at pagtatago ng shirk.", "Ang nakatagong shirk ay higit na lihim kaysa sa gumagapang na langgam."),
        "dua_rain" to DuaText("Kapag Umuulan", "O Allah, (magpadala) ng isang kapaki-pakinabang na ulan.", "Kapag umuulan.", "Ang ulan ay isang panahon kung kailan tinatanggap ang mga duas."),
        "dua_after_rain" to DuaText("Pagkatapos ng Ulan", "Kami ay binigyan ng ulan sa pamamagitan ng kagandahang-loob ni Allah at ng Kanyang awa.", "Pagkatapos ng ulan.", "Ang nagsabi nito ay isang mananampalataya kay Allah."),
        "dua_istisqa" to DuaText("Humihingi ng Ulan (Istisqa)", "O Allah, padalhan mo kami ng ulan (tatlong beses).", "Kapag walang ulan.", "Ginawa ng Propeta ﷺ ang dua na ito sa sermon ng Biyernes at umulan."),
        "dua_heavy_rain" to DuaText("Labis na Ulan", "O Allah, (hayaang bumagsak ito) sa paligid namin at hindi sa amin.", "Kapag sobrang lakas ng ulan.", "Ang mga ulap ay lumayo sa pamamagitan ng dua ng Propeta ﷺ."),
        "dua_wind" to DuaText("Kapag Umihip ang Hangin", "O Allah, hinihiling ko sa Iyo ang kabutihan nito, ang kabutihan sa loob nito at ang kabutihan ng kung ano ang ipinadala nito, at ako ay nagpapakupkop sa Iyo mula sa kasamaan nito, ang kasamaan sa loob nito at ang kasamaan ng kung ano ang ipinadala nito.", "Kapag umihip ang malakas na hangin o bagyo.", "Ginawa ng Propeta ﷺ ang dua na ito sa panahon ng mga bagyo."),
        "dua_thunder" to DuaText("Naririnig si Thunder", "Luwalhati sa Isa na niluluwalhati ng kulog sa Kanyang papuri, at ang mga anghel dahil sa takot sa Kanya.", "Sa pagdinig ng kulog — ang pagsasanay ni Abdullah ibn az-Zubayr (RA).", "Kinuha mula sa Surah ar-Ra'd (13:13)."),
        "dua_new_moon" to DuaText("Nakikita ang Bagong Buwan", "O Allah, hayaang sumikat ang buwan na ito sa amin nang may pagpapala, pananampalataya, kaligtasan at Islam. (O buwan,) aking Panginoon at ang iyong Panginoon ay si Allah.", "Nang makita ang bagong buwan.", "Ang Sunnah dua para sa bawat bagong buwan."),
        "dua_janaza_adult" to DuaText("Panalangin ng Janaza (Matanda)", "O Allah, patawarin mo ang aming mga buhay at ang aming mga patay, ang mga naroroon at ang mga wala, ang aming mga bata at aming matanda, ang aming mga kalalakihan at kababaihan. O Allah, sinuman sa amin ang Iyong pinapanatili mong buhay, buhayin mo siyang buhay sa Islam, at sinuman sa amin ang Iyong pinapatay, patayin mo siya sa pananampalataya.", "Pagkatapos ng ikatlong takbir ng pagdarasal sa libing.", "Ang Sunnah dua para sa isang namatay na nasa hustong gulang."),
        "dua_janaza_child" to DuaText("Panalangin ng Janaza (Bata)", "O Allah, gawin mo siyang isang tagapagpauna (at host) para sa amin, gawin siyang isang gantimpala at isang kayamanan para sa amin, at gawin siyang isang tagapamagitan para sa amin na ang pamamagitan ay tinatanggap.", "Sa panalangin ng libing ng isang bata (para sa isang batang babae sabihin ang 'ij'alhā').", "Ang Sunnah dua na isinagawa ng mga Hanafi."),
        "dua_mayyit_awf" to DuaText("Detalyadong Dua para sa Namatay", "O Allah, patawarin mo siya, maawa ka sa kanya, bigyan mo siya ng kagalingan at patawarin mo siya. Gawing marangal ang kanyang pagtanggap at maluwang ang kanyang libingan, hugasan siya ng tubig, niyebe at granizo, at linisin siya sa mga kasalanan tulad ng isang puting damit na nililinis sa dumi.", "Sa panalangin sa libing o para sa namatay.", "Nais ni Awf ibn Malik (RA) na siya ang namatay na tao."),
        "dua_visiting_graves" to DuaText("Pagbisita sa mga libingan", "Sumainyo nawa ang kapayapaan, O mananampalataya at Muslim na naninirahan sa mga tahanan na ito. Kami rin, kung gugustuhin ni Allah, ay sasamahan kayo. Hinihiling ko sa Allah ang kapakanan para sa amin at para sa iyo.", "Pagpasok sa libingan.", "Ang pagbisita sa mga libingan ay nagpapaalala sa isa sa kamatayan at sa Kabilang Buhay."),
        "dua_closing_eyes" to DuaText("Sa Pagpikit ng mga Mata ng Namatay", "O Allah, patawarin mo si (pangalan), itaas ang kanyang ranggo sa mga napatnubayan, maging kahalili niya sa mga iniwan niya. Patawarin mo kami at siya, O Panginoon ng mga mundo; palawakin ang kanyang libingan at punuin ito ng liwanag.", "Kapag nakapikit ang mga mata ng namatay (binabanggit ang kanyang pangalan).", "Ginawa ng Propeta ﷺ ang dua para kay Abu Salamah (RA)."),
        "dua_condolence" to DuaText("Pakikiramay (Ta'ziyah)", "Katiyakang kay Allah ang Kanyang kinuha at sa Kanya ang Kanyang ibinigay, at lahat ng bagay sa Kanya ay may takdang panahon, kaya maging matiyaga at umasa sa gantimpala.", "Nag-aalok ng pakikiramay sa isang pamilya pagkatapos ng kamatayan.", "Ipinadala ng Propeta ﷺ ang mensaheng ito sa kanyang anak na babae."),
        "dua_placing_in_grave" to DuaText("Paglalagay ng Namatay sa Libingan", "Sa pangalan ng Allah at sa daan ng Sugo ng Allah ﷺ.", "Kapag ibinaba ang namatay sa libingan.", "Ang Sunnah dua ng libing."),
        "dua_sneezing" to DuaText("Bumahing", "Ang lahat ng papuri ay para sa Allah. — Kaawaan ka nawa ng Allah. — Nawa'y patnubayan ka ng Allah at ayusin ang iyong mga gawain.", "Sa pagbahin; ang nakikinig ay nagsasabi ng 'Yarhamukallah', pagkatapos ay ang bumahing ay tumugon.", "Ito ay isa sa mga karapatan ng isang Muslim sa ibang Muslim."),
        "dua_toilet_enter" to DuaText("Pagpasok sa Toilet", "Sa ngalan ni Allah. O Allah, ako ay nagpapakupkop sa Iyo mula sa maruming jinn na lalaki at babae.", "Bago humakbang sa palikuran gamit ang kaliwang paa.", "Ang Bismillah ay nagiging takip sa pagitan ng jinn at ng tao."),
        "dua_toilet_exit" to DuaText("Paglabas ng Toilet", "(O Allah,) Ako ay humihingi ng Iyong kapatawaran.", "Kapag lumalabas sa banyo gamit ang kanang paa.", "Ang Propeta ﷺ ay nagsabi nito sa paglabas ng palikuran."),
        "dua_thanking" to DuaText("Nagpapasalamat sa Isang Tao", "Nawa'y gantimpalaan ka ni Allah ng kabutihan.", "Kapag may nag-favor sayo.", "Ang sinumang nagsabi nito ay lubos na nagpahayag ng kanyang pasasalamat."),
        "dua_love_for_allah" to DuaText("Kapag May Nagsabi ng 'I Love You for Allah'", "Nawa'y Siya (Allah), para sa kapakanan na mahal mo ako, ay mahalin ka.", "Kapag may nagsabing 'Mahal kita para sa kapakanan ng Allah'.", "Ang Sunnah ay tumugon sa pagmamahal para sa kapakanan ng Allah."),
        "dua_seeing_muslim_smile" to DuaText("Pagbati (Salaam)", "Sumainyo nawa ang kapayapaan, at ang awa ng Allah at ang Kanyang mga pagpapala.", "Kapag nakikipagkita sa isang Muslim.", "Ang pagsasabi ng kumpletong salam ay kumikita ng tatlumpung kabutihan."),
        "dua_dressing" to DuaText("Nagbibihis", "Ang lahat ng papuri ay para sa Allah na nagbihis sa akin nito at nagbigay nito sa akin nang walang anumang lakas o kapangyarihan sa aking bahagi.", "Kapag nagbibihis.", "Masayang balita ng kapatawaran ng mga nakaraang kasalanan."),
    )
}
